SELECT COUNT(DISTINCT vendor_id) AS active_vendors_2026
FROM payments
WHERE paid_on >= '2026-01-01' AND paid_on < '2027-01-01';

real_questions.solution:
WITH ranked AS (
  SELECT customer_id, order_id, amount_usd, order_date,
    ROW_NUMBER() OVER (
      PARTITION BY customer_id
      ORDER BY amount_usd DESC, order_date ASC
    ) AS rk
  FROM orders
)
SELECT * FROM ranked WHERE rk <= 3;
